 useEffect(()=>{try{const p=JSON.parse(localStorage.getItem('coc-studio-panel-widths')||'null');if(p&&Number.isFinite(p.left)&&Number.isFinite(p.right))setPanelWidths({left:p.left,right:p.right});}catch{}setPanelsReady(true);},[]);
 useEffect(()=>{if(!panelsReady)return;try{localStorage.setItem('coc-studio-panel-widths',JSON.stringify(panelWidths));}catch{}},[panelWidths,panelsReady]);
 useEffect(()=>{if(!workspace.current)return;const observer=new ResizeObserver(([e])=>setWorkspaceWidth(e.contentRect.width));observer.observe(workspace.current);return()=>observer.disconnect();},[loaded]);
 useEffect(()=>{setPanelWidths(p=>{const fitted=fitPanels(p,workspaceWidth,collapsed);return fitted.left===p.left&&fitted.right===p.right?p:fitted;});},[workspaceWidth,collapsed]);
 const startPanelResize=(e:React.PointerEvent,side:'left'|'right')=>{if(e.button!==0)return;e.preventDefault();e.stopPropagation();e.currentTarget.setPointerCapture(e.pointerId);panelDrag.current={side,start:e.clientX,original:panelWidths,total:workspaceWidth};};
 const movePanelResize=(e:React.PointerEvent)=>{const d=panelDrag.current;if(!d)return;e.preventDefault();setPanelWidths(resizePanel(d.original,d.side,(e.clientX-d.start)*(d.side==='right'?-1:1),d.total,collapsed));};
 const panelKeyboard=(e:React.KeyboardEvent,side:'left'|'right')=>{if(e.key==='Home'){e.preventDefault();setPanelWidths({left:235,right:213});return;}if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const step=(e.key==='ArrowRight'?1:-1)*(side==='right'?-1:1)*(e.shiftKey?40:10);setPanelWidths(p=>resizePanel(p,side,step,workspaceWidth,collapsed));};
 const stateRef=useRef(state),dirtyRef=useRef(false),editingSeq=useRef(0),saving=useRef(false),canvas=useRef<HTMLDivElement>(null),viewport=useRef<HTMLDivElement>(null),fit=useRef(0.6),drag=useRef<any>(null),fileInput=useRef<HTMLInputElement>(null),importInput=useRef<HTMLInputElement>(null),imageTarget=useRef(''),pageDrag=useRef('');
 stateRef.current=state;dirtyRef.current=dirty;
 const notify=useCallback((message:string)=>{setToast(message);setTimeout(()=>setToast(''),4200);},[]);
 const loadCatalog=useCallback(async()=>{const r=await fetch('/api/scenarios',{cache:'no-store'});if(!r.ok)throw Error('シナリオ一覧を取得できませんでした。');const data=await r.json() as {scenarios:ScenarioSummary[]};setScenarios(data.scenarios);return data.scenarios;},[]);
 const load=useCallback(async()=>{const requested=new URL(window.location.href).searchParams.get('scenario');const r=requested?await fetch('/api/scenarios',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'open',scenarioId:requested})}):await fetch('/api/studio',{cache:'no-store'});if(!r.ok)throw Error('保存データを読み込めませんでした。');const s=await r.json() as Store;stateRef.current=s;setState(s);setPageId(s.doc.pages.some((p:Page)=>p.id===s.selection.pageId)?s.selection.pageId:s.doc.pages[0].id);setSaveStatus('保存済み');setLoaded(true);const url=new URL(window.location.href);url.searchParams.set('scenario',s.scenarioId!);window.history.replaceState(null,'',url);loadCatalog().catch(e=>notify(e.message));},[loadCatalog,notify]);
 useEffect(()=>{load().catch(e=>{setSaveStatus('読込失敗');notify(e.message);});},[load,notify]);
 const post=async(action:string,values:any={})=>{const scenarioId=stateRef.current?.scenarioId;if(values.scenarioId&&values.scenarioId!==scenarioId)throw Error('別のシナリオのデータです。対象を確認してください。');const r=await fetch('/api/studio',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...values,scenarioId})});const result=await r.json() as any;if(!r.ok)throw Error(result.error||'更新に失敗しました。');return result as Store;};
 const persist=useCallback(async()=>{if(!stateRef.current||!dirtyRef.current||saving.current)return !dirtyRef.current;saving.current=true;setSaveStatus('保存中…');const s=stateRef.current,seq=editingSeq.current;try{const next=await post('save',{doc:s.doc,baseRevision:s.contentRevision});const merged={...next,doc:editingSeq.current===seq?next.doc:stateRef.current!.doc};stateRef.current=merged;setState(merged);if(editingSeq.current===seq){setDirty(false);dirtyRef.current=false;}setSaveStatus('保存済み');return true;}catch(e){setSaveStatus('保存失敗');notify((e as Error).message);return false;}finally{saving.current=false;}},[notify]);
 useEffect(()=>{if(!dirty)return;const t=setTimeout(()=>persist(),850);return()=>clearTimeout(t);},[dirty,state,persist]);
 useEffect(()=>{const poll=setInterval(async()=>{if(dirtyRef.current||saving.current||transitioning.current)return;const scenarioId=stateRef.current?.scenarioId;if(!scenarioId)return;try{const r=await fetch('/api/studio?scenarioId='+encodeURIComponent(scenarioId),{cache:'no-store'});if(r.ok){const next=await r.json() as Store;if(!dirtyRef.current&&!saving.current&&!transitioning.current&&stateRef.current?.scenarioId===scenarioId)setState(next);}}catch{}},6000);return()=>clearInterval(poll);},[]);
 useEffect(()=>{const h=(e:BeforeUnloadEvent)=>{if(dirtyRef.current){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',h);return()=>window.removeEventListener('beforeunload',h);},[]);
 useEffect(()=>{if(!viewport.current)return;const ro=new ResizeObserver(([e])=>{fit.current=Math.min((e.contentRect.width-16)/1280,(e.contentRect.height-16)/720);setZoom(z=>z===1?1:z);});ro.observe(viewport.current);return()=>ro.disconnect();},[loaded,mode,collapsed]);
 useEffect(()=>{if(!state||dirty||!state.doc.pages.some(p=>p.id===pageId))return;post('select',{pageId,objectId:selected||undefined}).catch(()=>{});},[pageId,selected,dirty,state?.contentRevision,state?.scenarioId]);
 const [viewportSize,setViewportSize]=useState({w:900,h:650});
 useEffect(()=>{if(!viewport.current)return;const ro=new ResizeObserver(([e])=>setViewportSize({w:e.contentRect.width,h:e.contentRect.height}));ro.observe(viewport.current);return()=>ro.disconnect();},[loaded,mode,collapsed]);
 const change=useCallback((fn:(d:Doc)=>void)=>{editingSeq.current++;dirtyRef.current=true;setDirty(true);setSaveStatus('未保存');setState(s=>{if(!s)return s;const d=structuredClone(s.doc);fn(d);d.pages=orderPages(d.pages);return {...s,doc:d};});},[]);
 const page=state?.doc.pages.find(p=>p.id===pageId)||state?.doc.pages[0];const obj=page?.objects.find(x=>x.id===selected);const scale=Math.max(.18,Math.min((viewportSize.w-16)/1280,(viewportSize.h-16)/720))*zoom;
 const updateObj=(id:string,patch:Partial<Obj>)=>change(d=>{const o=d.pages.find(p=>p.id===pageId)?.objects.find(o=>o.id===id);if(o)Object.assign(o,patch);});
 const choosePage=async(id:string)=>{setPageId(id);setSelected(null);setMode('editor');try{await post('select',{pageId:id});}catch(e){notify((e as Error).message);}};
 const addObject=(o:Partial<Obj>)=>{if(!page)return;const id=uid();change(d=>d.pages.find(p=>p.id===page.id)!.objects.push({type:'text',x:100,y:100,w:440,h:200,size:23,color:'#414b42',text:'新しいテキスト',...o,id}));setSelected(id);};
 const addEntityObject=(e:Entity,x=900,y=190)=>{addObject({type:'entity',entityId:e.id,x:Math.min(1040,Math.max(0,x)),y:Math.min(360,Math.max(0,y)),w:220,h:340});notify(e.name+'を配置しました');};
 const removeObj=()=>{if(obj?.label){notify('入力欄は削除できません。内容を空欄にできます。');return;}if(obj)change(d=>{d.pages.find(p=>p.id===pageId)!.objects=d.pages.find(p=>p.id===pageId)!.objects.filter(o=>o.id!==obj.id);});setSelected(null);};
 const duplicateObj=()=>{if(obj)addObject({...obj,label:undefined,id:undefined,x:Math.min(1280-obj.w,obj.x+24),y:Math.min(720-obj.h,obj.y+24)});};
 useEffect(()=>{const key=(e:KeyboardEvent)=>{if(busy||(e.target as HTMLElement)?.matches('input,textarea,select,[contenteditable]')||modal)return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeObj();}if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();persist();}if((e.ctrlKey||e.metaKey)&&e.key==='d'){e.preventDefault();duplicateObj();}if(e.key==='Escape'){setSelected(null);setFocusMode(false);}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);});
 const pointerStart=(e:React.PointerEvent,o:Obj,direction?:ResizeDirection)=>{if(e.button!==0)return;e.stopPropagation();e.preventDefault();(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);setSelected(o.id);drag.current={id:o.id,x:e.clientX,y:e.clientY,original:{...o},direction,scale};};
 const pointerMove=(e:React.PointerEvent)=>{if(!drag.current)return;e.stopPropagation();const a=drag.current,dx=(e.clientX-a.x)/a.scale,dy=(e.clientY-a.y)/a.scale;if(a.direction)updateObj(a.id,resizeBox(a.original,a.direction,dx,dy));else updateObj(a.id,{x:Math.round(Math.max(0,Math.min(1280-a.original.w,a.original.x+dx))),y:Math.round(Math.max(0,Math.min(720-a.original.h,a.original.y+dy)))});};
 const pointerEnd=()=>{drag.current=null;};
