 const copyContext=async()=>{if(dirtyRef.current&&!(await persist()))return;const s=stateRef.current!;await post('select',{pageId:page?.id,objectId:selected||undefined}).catch(()=>{});const prompt=`CoC Scenario Studioのシナリオ「${s.doc.title}」（scenarioId: ${s.scenarioId}）の「${page?.title}」を相談したい。対象のシナリオ名・IDを必ず確認し、以後の読み取りと提案にscenarioIdを指定してください。他シナリオの設定を混ぜないでください。${notationInstructions}\nまずget_project_contextにscenarioIdを指定して最新版と選択ページを取得し、get_architect_rulesでv1.9の関連規則を読んでください。確定設定を維持し、因果関係・NPCの知識の来歴・PCの選択を検証してください。右側の構成はタイトルと概要・リード・はじめに・KP向け情報・PL向け情報・NPC（一人1枚）・シーン（1場面1枚）・最後に備考です。概要は導入から結末まで400字程度で本編字数の対象外。リード以降が本編です。未決定の内容は空欄にしてください。提案はpropose_changesで登録し、Web上で採用を待ってください。\n\n相談内容：\n\n【MCPが利用できない場合の参照データ】\n${JSON.stringify({scenarioId:s.scenarioId,title:s.doc.title,contentRevision:s.contentRevision,page,canon:s.doc.canon,entities:s.doc.entities,issues:s.doc.issues},null,2)}\n\n変更案JSON形式：{ "scenarioId":"${s.scenarioId}", "title":"提案名", "summary":"変更理由", "baseRevision":${s.contentRevision}, "operations":[{"action":"add_object","targetId":"${page?.id}","value":{"id":"一意ID","type":"text","x":80,"y":500,"w":700,"h":150,"text":"追加する情報","size":21}}],"review":{"majorIssues":0,"notes":"因果・知識経路・確定設定との整合の検証結果"}}`;
 try{await navigator.clipboard.writeText(prompt);notify('選択ページと相談文をコピーしました');}catch{setModal({kind:'copy',text:prompt});}};
 const onImage=async(e:React.ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(file.size>8*1024*1024){notify('画像は8MB以下です');return;}const uploadScenarioId=stateRef.current?.scenarioId;try{const r=await fetch('/api/assets',{method:'POST',headers:{'Content-Type':file.type},body:file});const result=await r.json() as any;if(!r.ok)throw Error(result.error);if(stateRef.current?.scenarioId!==uploadScenarioId)throw Error('画像の読込中にシナリオが切り替わりました。対象のシナリオで再度追加してください。');if(imageTarget.current==='canvas')addObject({type:'image',src:result.src,label:file.name,w:350,h:350});else{change(d=>{const e=d.entities.find(e=>e.id===imageTarget.current);if(e)e.image=result.src;});setModal((m:any)=>m?.kind==='entity'?{...m,value:{...m.value,image:result.src}}:m);}notify('画像を追加しました');}catch(e){notify((e as Error).message);}};
